package com.automationstudio.engine.karate;
import static org.junit.jupiter.api.Assertions.*;import com.automationstudio.engine.sdk.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class GatewaySecretBrokerTest{
 @Test void resolvesLateAndClosesAfterMaterialization()throws Exception{AtomicInteger resolutions=new AtomicInteger(),closes=new AtomicInteger();UUID id=UUID.randomUUID();ExecutionSecretAccess access=new ExecutionSecretAccess(){public UUID executionId(){return id;}public ResolvedSecret resolve(String name){assertEquals("logical",name);resolutions.incrementAndGet();return new TrackingSecret("canary".toCharArray(),closes);}};var values=new LinkedHashMap<String,Object>(KarateTestFixtures.configuration());values.put("secretReferences",Map.of("token","logical"));values.put("authentication",Map.of("type","bearer","secretRef","token"));var output=new ByteArrayOutputStream();new GatewaySecretBroker(access,KarateSuiteConfiguration.parse(values)).materialize(new DataOutputStream(output));assertEquals(1,resolutions.get());assertEquals(1,closes.get());assertTrue(output.size()>0);}
 @Test void noneDoesNotResolve()throws Exception{UUID id=UUID.randomUUID();AtomicInteger resolutions=new AtomicInteger();ExecutionSecretAccess access=new ExecutionSecretAccess(){public UUID executionId(){return id;}public ResolvedSecret resolve(String name){resolutions.incrementAndGet();throw new AssertionError();}};new GatewaySecretBroker(access,KarateSuiteConfiguration.parse(KarateTestFixtures.configuration())).materialize(new DataOutputStream(new ByteArrayOutputStream()));assertEquals(0,resolutions.get());}
 private static final class TrackingSecret extends ResolvedSecret{private final AtomicInteger closes;TrackingSecret(char[] value,AtomicInteger closes){super(value);this.closes=closes;}@Override public synchronized void close(){super.close();closes.incrementAndGet();}}
}
